-- 17 solicitudes de cancelación de Airtable (tabla solicitudes_de_cancelacion, dic-2025 a mar-2026) que no llegaron
-- a base_general. Se importan «por revisar»: cliente y motivo resueltos desde Airtable, sin resultado (no se sabe si el
-- cliente se fue o se quedó). Cuentan como solicitudes recibidas, no como bajas ni retenidas; el equipo les pone
-- resultado desde la ficha. Llave: airtable_id de origen (no se duplica si se corre dos veces).
-- Reversa: delete from legacy.base_general where comentarios_de_seguimiento like '[Importada de Airtable el 16-nov-2026%';
begin;
insert into legacy.base_general (id, folio, folio_ticket, airtable_id, fecha_de_la_solicitud, mes, nombre_del_cliente_nuevo, tipo_de_incidencia,
