       correo_del_contacto, telefono_del_contacto, tipo_de_servicio, tipo_de_solicitud, status, comentarios_de_seguimiento)
select (select coalesce(max(id),0) from legacy.base_general) + row_number() over (order by v.fecha, v.airtable_id),
